function g({registerIndicator:w,sourceValues:y,nulls:u}){function f(o){const i=new Array(o).fill(0);i[0]=1;let r=1;for(let e=1;e<o;e++){const n=r*(o-e)/e;i[e]=n,r=n}return i}w({id:"oa-pwma",name:"Pascal Weighted Moving Average (PWMA)",category:"Trends FIR",placement:"onchart",inputs:[{key:"period",type:"number",label:"Period",default:10,min:1,max:1e3,step:1},{key:"source",type:"source",label:"Source",default:"close"}],plots:[{key:"pwma",type:"line",title:"PWMA",style:{color:"#ffeb3b",lineWidth:2}}],calc(o,i){const r=Math.max(1,Math.floor(Number(i.period)||10)),e=y(o,i.source??"close"),n=o.length,a=new Array(n).fill(NaN);if(n===0)return{pwma:u(a)};const b=f(r);for(let t=0;t<n;t++){const c=Math.min(t+1,r),m=c===r?b:f(c);let p=0,s=0;for(let l=0;l<c;l++){const h=e[t-l];Number.isFinite(h)&&(p+=h*m[l],s+=m[l])}const d=s>0?p/s:NaN;Number.isFinite(d)?a[t]=d:Number.isFinite(e[t])&&(a[t]=e[t])}return{pwma:u(a)}}})}export{g as default};
